$ErrorActionPreference='Stop'
$taskRoot=(Resolve-Path (Join-Path $PSScriptRoot '../../..')).Path
$taskOut=Join-Path $taskRoot 'assets/ui/hud/r3_v1'
$taskFamilies=@('ui.hud.identity_status','ui.hud.quest_context','ui.hud.touch','ui.hud.five_slot_cluster','ui.hud.radial.art','ui.hud.minimap','ui.hud.guides_pause','ui.hud.forbidden_presentation','ui.theme_fonts_icons')
$taskRecords=@(foreach($taskFile in Get-ChildItem -LiteralPath $taskOut -File|Where-Object {$_.Extension -notin @('.import','.uid') -and $_.Name -ne 'catalog.json'}){[ordered]@{path=[IO.Path]::GetRelativePath($taskRoot,$taskFile.FullName).Replace('\','/');sha256=(Get-FileHash -LiteralPath $taskFile.FullName -Algorithm SHA256).Hash;bytes=$taskFile.Length;owner='R3 009';consumer='UI/HUD/WorldHUD.tscn';dependencies=@('R3 007 original identity','R3 008 four modes');action='new'}})
$taskReuse=@('assets/characters/cast/explorer/portraits/explorer_neutral.png','assets/ui/icons/mobile_sprint.svg','assets/fonts/InterfaceSans.tres','Scripts/Content/phase_device_progress.gd')
foreach($taskMode in @('thermal','cryo','vacuum','pressure')){$taskReuse+='assets/ui/phase_dial/v1/'+$taskMode+'_icon.svg'}
$taskReuseRecords=@(foreach($taskPath in $taskReuse){[ordered]@{path=$taskPath;sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot $taskPath) -Algorithm SHA256).Hash;action='keep';owner='R3 009 compatibility';consumer='UI/HUD/WorldHUD.tscn'}})
$taskPresentation=@(foreach($taskPath in @('Scripts/UI/WorldHUD/world_hud.gd','Scripts/UI/WorldHUD/hud_action.gd','Scripts/UI/WorldHUD/hud_minimap.gd','UI/HUD/WorldHUD.tscn','tools/art/hud_r3_v1/build.ps1','tools/art/hud_r3_v1/generation.md')){[ordered]@{path=$taskPath;sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot $taskPath) -Algorithm SHA256).Hash;owner='R3 009';action='new'}})
[ordered]@{schema_version=1;owner='R3 009';status='Implemented—needs verification; user/Android pending';scene='UI/HUD/WorldHUD.tscn';runtime='Opt-in presentation only; current CampaignHUD remains authoritative until015';families=$taskFamilies;files=$taskRecords;reused=$taskReuseRecords;presentation_sources=$taskPresentation;source_project='tools/art/hud_r3_v1/build.ps1';source_notes='tools/art/hud_r3_v1/generation.md';mode_mapping=[ordered]@{upper_left='vacuum';upper_right='pressure';lower_left='thermal';lower_right='cryo';central_hexagon='committed selected-mode display; cancel preview, no mode selection/fire/unlock'};minimum_landscape_safe_inner=@(540,300);safe_margin_ui=8;minimum_action_ui=44;minimum_mode_circle_ui=52;minimum_status_quest_font_ui=12;minimum_button_font_ui=11;landscape='Responsive per viewport, not downsampled desktop';portrait='Rotate-device fallback; no overlapping controls';retirement_eligible=$false;production_input_binding='R3 015; providers own saves, eligibility, discovery, target and action routing';render_style='Editable native SVG + Godot vector panels; retained original portrait/font/mode/run glyphs'}|ConvertTo-Json -Depth 12|Set-Content (Join-Path $taskOut catalog.json) -Encoding utf8
$taskManifestPath=Join-Path $taskRoot 'docs/audits/r3-prompt001/asset-manifest.json'
$taskManifest=Get-Content -Raw -LiteralPath $taskManifestPath|ConvertFrom-Json -AsHashtable
foreach($taskFamily in $taskManifest.families){if($taskFamily.id -notin $taskFamilies){continue};$taskFamily.review_status='R3 009 shared opt-in HUD presentation implemented—needs verification; world wiring015/user/Android pending';$taskFamily.r3_009=[ordered]@{owner='R3 009';catalog='assets/ui/hud/r3_v1/catalog.json';scene='UI/HUD/WorldHUD.tscn';coverage='docs/art/r3-prompt009/coverage.json';evidence='docs/art/r3-prompt009/evidence/results.json';consumer='Opt-in shared WorldHUD; no campaign binding yet';dependencies=@('R3 007 original identity','R3 008 four-mode contract','R3 015 authoritative world/input providers');disposition=$(if($taskFamily.action -eq 'retire'){'exclude from new HUD; keep current consumers until integration'}else{'new presentation/reuse original sources'});retirement_eligible=$false;replacement_dependency='Current CampaignHUD/radial/map/hotbar files stay until integrated replacement and retirement checks'}}
$taskManifest|ConvertTo-Json -Depth 40|Set-Content -LiteralPath $taskManifestPath -Encoding utf8
Write-Output ('R3 009 catalog: '+$taskRecords.Count+' native resources, '+$taskReuseRecords.Count+' reused sources, '+$taskFamilies.Count+' existing family bindings')
